import java.util.*;

class MyHashSet {
    int size = 1009;                                     // a fixed, moderately large bucket count
    List<List<Integer>> buckets = new ArrayList<>();

    MyHashSet() {
        for (int i = 0; i < size; i++) buckets.add(new ArrayList<>());
    }

    int hash(int key) { return key % size; }

    void add(int key) {
        List<Integer> bucket = buckets.get(hash(key));
        if (!bucket.contains(key)) bucket.add(key);       // only scan within this one bucket
    }

    void remove(int key) {
        buckets.get(hash(key)).remove(Integer.valueOf(key));
    }

    boolean contains(int key) {
        return buckets.get(hash(key)).contains(key);        // only scan within this one bucket
    }
}

