#include <bits/stdc++.h>
using namespace std;

class MyHashSet {
public:
    int size = 1009;                                       // a fixed, moderately large bucket count
    vector<vector<int>> buckets;

    MyHashSet() : buckets(size) {}

    int hashKey(int key) { return key % size; }

    void add(int key) {
        auto& bucket = buckets[hashKey(key)];
        if (find(bucket.begin(), bucket.end(), key) == bucket.end())  // only scan this bucket
            bucket.push_back(key);
    }

    void remove(int key) {
        auto& bucket = buckets[hashKey(key)];
        auto it = find(bucket.begin(), bucket.end(), key);
        if (it != bucket.end()) bucket.erase(it);
    }

    bool contains(int key) {
        auto& bucket = buckets[hashKey(key)];
        return find(bucket.begin(), bucket.end(), key) != bucket.end();  // only scan this bucket
    }
};
